import React, { useEffect, useState } from "react";

function Search() {
  const [buses, setBuses] = useState([]);
  const [filteredBuses, setFilteredBuses] = useState([]);
  const [source, setSource] = useState("");
  const [destination, setDestination] = useState("");

  const [sortOption, setSortOption] = useState("");
  const [filterType, setFilterType] = useState("All");

  // ✅ Fetch buses from backend
  useEffect(() => {
    fetch("http://localhost:5000/api/buses")
      .then((res) => res.json())
      .then((data) => {
        setBuses(data);
        setFilteredBuses(data);
      })
      .catch((err) => console.log("API Error:", err));
  }, []);

  // ⭐ Cheapest bus calculation
  const cheapestFare =
    filteredBuses.length > 0
      ? Math.min(...filteredBuses.map((bus) => bus.fare))
      : null;

  // ✅ Search + Sort + Filter Logic
  const handleSearch = () => {
    let results = buses.filter(
      (bus) =>
        bus.source.toLowerCase().includes(source.toLowerCase()) &&
        bus.destination.toLowerCase().includes(destination.toLowerCase())
    );

    // ✅ Filter
    if (filterType !== "All") {
      results = results.filter((bus) => bus.type === filterType);
    }

    // ✅ Sort
    if (sortOption === "fareLow") {
      results = [...results].sort((a, b) => a.fare - b.fare);
    } else if (sortOption === "fareHigh") {
      results = [...results].sort((a, b) => b.fare - a.fare);
    } else if (sortOption === "timeEarly") {
      results = [...results].sort((a, b) =>
        a.time.localeCompare(b.time)
      );
    }

    setFilteredBuses(results);
  };

  return (
    <div className="p-6 text-center">
      <h1 className="text-3xl font-bold mb-6">🚌 Bus Schedules</h1>

      {/* Search */}
      <div className="flex justify-center gap-4 mb-4">
        <input
          type="text"
          placeholder="Source"
          value={source}
          onChange={(e) => setSource(e.target.value)}
          className="border p-2 rounded"
        />

        <input
          type="text"
          placeholder="Destination"
          value={destination}
          onChange={(e) => setDestination(e.target.value)}
          className="border p-2 rounded"
        />

        <button
          onClick={handleSearch}
          className="bg-blue-600 text-white px-4 py-2 rounded"
        >
          Search
        </button>
      </div>

      {/* Sort + Filter */}
      <div className="flex justify-center gap-4 mb-6">

        <select
          onChange={(e) => setSortOption(e.target.value)}
          className="border p-2 rounded"
        >
          <option value="">Sort By</option>
          <option value="fareLow">Fare → Low to High</option>
          <option value="fareHigh">Fare → High to Low</option>
          <option value="timeEarly">Time → Early First</option>
        </select>

        <select
          onChange={(e) => setFilterType(e.target.value)}
          className="border p-2 rounded"
        >
          <option value="All">All Buses</option>
          <option value="AC">AC</option>
          <option value="Ordinary">Ordinary</option>
          <option value="Volvo">Volvo / Premium</option>
        </select>

      </div>

      {/* Bus List */}
      {filteredBuses.length > 0 ? (
        <div className="space-y-4 max-w-xl mx-auto">
          {filteredBuses.map((bus) => (
            <div
              key={bus._id}
              className={`p-4 rounded shadow border ${
                bus.fare === cheapestFare
                  ? "bg-green-100 border-green-500"
                  : "bg-gray-50"
              }`}
            >
              <h2 className="text-xl font-bold">{bus.name}</h2>

              <p>
                🚏 {bus.source} → {bus.destination}
              </p>

              <p>🕒 {bus.time}</p>

              <p>🚌 Type: {bus.type}</p>

              <p className="text-green-600 font-semibold">
                💰 ₹{bus.fare}
              </p>

              {bus.fare === cheapestFare && (
                <p className="text-green-700 font-bold text-sm">
                  ⭐ Cheapest Bus
                </p>
              )}
            </div>
          ))}
        </div>
      ) : (
        <p>No buses found</p>
      )}
    </div>
  );
}

export default Search;
